INSERT INTO public.mcq_banks (subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order) VALUES
('physics',1,'Capacitors','Isolated conductors','en','A single isolated charged spherical conductor is rarely used to store large electric charges because:','["Its surface area is too small to hold charge.", "Increasing its charge drastically raises its potential, causing electrostatic discharge into the surrounding air.", "It can only store negative charges.", "It lacks electrical resistance."]'::jsonb,1,'Ministerial-style bank',100),
('physics',1,'Capacitors','Isolated conductors','en','The electric potential V at a distance r from the center of an isolated charged solid spherical conductor carrying charge Q in air is calculated using:','["V = k r / Q", "V = k Q / r", "V = k Q / r²", "V = Q / (ε₀ r)"]'::jsonb,1,'Ministerial-style bank',101),
('physics',1,'Capacitors','Isolated conductors','en','What happens to air around an isolated spherical conductor when its electric field exceeds approximately 3 × 10⁶ V/m?','["The air turns into a perfect insulator.", "Electrical breakdown occurs, causing charge leakage into the air.", "The conductor loses its potential while retaining its charge.", "The surrounding air freezes."]'::jsonb,1,'Ministerial-style bank',102),
('physics',1,'Capacitors','Isolated conductors','en','A system consisting of two conductors separated by an insulator, designed to store electric charge and electrical energy, is called a:','["Resistor", "Inductor", "Capacitor", "Galvanometer"]'::jsonb,2,'Ministerial-style bank',103),
('physics',1,'Capacitors','Isolated conductors','en','In a parallel-plate capacitor, the electric field E between the plates (away from the edges) is considered uniform because:','["The distance between the plates is much smaller than the linear dimensions of the plates.", "The plates are made of non-conducting material.", "The potential difference is always zero.", "The plates are connected to an AC source."]'::jsonb,0,'Ministerial-style bank',104),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','Capacitance (C) is defined mathematically as the ratio of:','["Electric field to distance between plates (E / d)", "Stored electric charge on either plate to the potential difference between them (Q / ΔV)", "Potential difference to stored charge (ΔV / Q)", "Stored potential energy to resistance (PE / R)"]'::jsonb,1,'Ministerial-style bank',105),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','The standard SI unit of capacitance is the Farad (F). One Farad is equivalent to:','["1 Volt / Coulomb", "1 Coulomb × Volt", "1 Coulomb / Volt", "1 Joule / Coulomb"]'::jsonb,2,'Ministerial-style bank',106),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','Which unit conversion is correct?','["1 μF = 10⁻³ F", "1 nF = 10⁻⁶ F", "1 pF = 10⁻¹² F", "1 mF = 10⁻¹² F"]'::jsonb,2,'Ministerial-style bank',107),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','The electric field E between two parallel charged plates separated by distance d under potential difference ΔV is given by:','["E = ΔV · d", "E = ΔV / d", "E = d / ΔV", "E = Q / (ΔV · d)"]'::jsonb,1,'Ministerial-style bank',108),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','How does the capacitance of a parallel-plate capacitor change if the overlapping surface area A of its plates is doubled while keeping all other factors constant?','["It is halved.", "It doubles.", "It quadruples.", "It remains unchanged."]'::jsonb,1,'Ministerial-style bank',109),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','How does capacitance change if the distance d between the plates is reduced to one-third of its original value?','["It decreases to 1/3 of its original value.", "It remains unchanged.", "It increases to 3 times its original value.", "It increases to 9 times its original value."]'::jsonb,2,'Ministerial-style bank',110),
('physics',1,'Capacitors','Capacitance & parallel-plate parameters','en','The mathematical formula for the capacitance of a parallel-plate capacitor with air as the dielectric is:','["C = ε₀ d / A", "C = ε₀ A / d", "C = ε₀ A d", "C = A / (ε₀ d)"]'::jsonb,1,'Ministerial-style bank',111),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','Polar dielectrics (such as pure water) differ from non-polar dielectrics because polar dielectrics:','["Possess permanent electric dipole moments.", "Acquire temporary dipole moments only when exposed to an electric field.", "Conduct electricity easily.", "Do not interact with external electric fields."]'::jsonb,0,'Ministerial-style bank',112),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','When a non-polar dielectric material (such as glass or paraffin) is placed inside an electric field, its molecules:','["Align permanently without acquiring charge.", "Become temporarily polarized due to displacement of positive and negative charge centers.", "Gain free electrons and turn into metallic conductors.", "Lose all electric dipole behavior."]'::jsonb,1,'Ministerial-style bank',113),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','The induced electric field E_d created inside a dielectric inserted between charged capacitor plates points in a direction:','["Parallel and in the same direction as the external electric field E.", "Opposite to the direction of the external electric field E.", "Perpendicular to the external electric field E.", "Circular around the plate edges."]'::jsonb,1,'Ministerial-style bank',114),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','The net electric field E_k inside a dielectric material placed in an external field E is given by:','["E_k = E + E_d", "E_k = E − E_d", "E_k = E · E_d", "E_k = E_d / E"]'::jsonb,1,'Ministerial-style bank',115),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','The dielectric constant k of a material is a dimensionless ratio defined as:','["k = C / C_k", "k = C_k / C", "k = ΔV_k / ΔV", "k = C_k − C"]'::jsonb,1,'Ministerial-style bank',116),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','In Faraday''s experiment using an electroscope connected to a charged, disconnected capacitor, inserting a dielectric slab causes the leaf deflection of the electroscope to:','["Increase, indicating an increase in potential difference.", "Decrease, indicating a decrease in potential difference.", "Drop immediately to zero.", "Remain unchanged."]'::jsonb,1,'Ministerial-style bank',117),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','What happens to the potential difference across a disconnected capacitor when a dielectric with constant k = 4 is inserted between its plates?','["It increases by 4 times.", "It decreases to 1/4 of its original value.", "It remains constant.", "It doubles."]'::jsonb,1,'Ministerial-style bank',118),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','Dielectric strength is defined as the maximum electric field a material can withstand before breakdown occurs. Its SI unit is:','["Volt · meter", "Volt / meter", "Farad / meter", "Coulomb / Volt"]'::jsonb,1,'Ministerial-style bank',119),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','If a dielectric material with k = 3 is inserted into a capacitor that remains connected to a DC battery, the potential difference across the plates:','["Triples.", "Drops to 1/3.", "Remains equal to the battery voltage.", "Becomes zero."]'::jsonb,2,'Ministerial-style bank',120),
('physics',1,'Capacitors','Dielectrics & experimental activities','en','If a dielectric with k = 5 is inserted into a capacitor connected to a 12 V battery, the charge on the capacitor:','["Decreases by a factor of 5.", "Increases by 5 times.", "Remains constant.", "Drops to zero."]'::jsonb,1,'Ministerial-style bank',121),
('physics',1,'Capacitors','Capacitor combinations','en','When capacitors are connected in parallel across a DC voltage source, which quantity remains identical across all individual capacitors?','["Electric charge (Q)", "Potential difference (ΔV)", "Stored energy (PE)", "Capacitance (C)"]'::jsonb,1,'Ministerial-style bank',122),
('physics',1,'Capacitors','Capacitor combinations','en','The primary practical reason for connecting capacitors in parallel is to:','["Increase equivalent capacitance and store larger amounts of electric charge at a given potential difference.", "Enable the system to withstand higher potential difference without breakdown.", "Reduce total stored energy.", "Convert DC current to AC current."]'::jsonb,0,'Ministerial-style bank',123),
('physics',1,'Capacitors','Capacitor combinations','en','The equivalent capacitance C_eq for three capacitors (C₁, C₂, C₃) connected in parallel is calculated as:','["C_eq = 1/C₁ + 1/C₂ + 1/C₃", "C_eq = C₁ + C₂ + C₃", "1/C_eq = 1/C₁ + 1/C₂ + 1/C₃", "C_eq = (C₁·C₂·C₃)/(C₁ + C₂ + C₃)"]'::jsonb,1,'Ministerial-style bank',124),
('physics',1,'Capacitors','Capacitor combinations','en','In a series connection of capacitors, the total charge Q_T supplied by the source is equal to:','["Q₁ + Q₂ + Q₃", "Q₁ = Q₂ = Q₃", "(Q₁ + Q₂)/Q₃", "Zero"]'::jsonb,1,'Ministerial-style bank',125),
('physics',1,'Capacitors','Capacitor combinations','en','What is the primary purpose of connecting capacitors in series?','["To maximize total charge storage.", "To apply a high potential difference across the combination that an individual capacitor could not withstand.", "To increase individual plate surface areas.", "To increase total equivalent capacitance."]'::jsonb,1,'Ministerial-style bank',126),
('physics',1,'Capacitors','Capacitor combinations','en','The equivalent capacitance C_eq of a series combination is always:','["Greater than the largest individual capacitance in the group.", "Equal to the average of all capacitances.", "Smaller than the smallest individual capacitance in the group.", "Double the value of the largest capacitance."]'::jsonb,2,'Ministerial-style bank',127),
('physics',1,'Capacitors','Capacitor combinations','en','Two capacitors with values C₁ = 6 μF and C₂ = 12 μF are connected in series. What is their equivalent capacitance C_eq?','["18 μF", "4 μF", "0.25 μF", "72 μF"]'::jsonb,1,'Ministerial-style bank',128),
('physics',1,'Capacitors','Capacitor combinations','en','Two capacitors (C₁ = 3 μF and C₂ = 6 μF) are connected in parallel to a 12 V battery. What is the total stored charge Q_T?','["36 μC", "72 μC", "108 μC", "144 μC"]'::jsonb,2,'Ministerial-style bank',129),
('physics',1,'Capacitors','Capacitor combinations','en','In a series combination of two unequal capacitors (C₁ < C₂), which capacitor experiences the larger potential difference?','["C₁ (the smaller capacitor)", "C₂ (the larger capacitor)", "Both experience the exact same potential difference.", "Neither experiences potential difference."]'::jsonb,0,'Ministerial-style bank',130),
('physics',1,'Capacitors','Capacitor combinations','en','If three identical capacitors of value C are connected in parallel, the equivalent capacitance is:','["C/3", "C", "3C", "9C"]'::jsonb,2,'Ministerial-style bank',131),
('physics',1,'Capacitors','Electric energy & variable conditions','en','Which of the following equations correctly represents the electric potential energy (PE_elec) stored in a charged capacitor?','["PE = ½ Q ΔV", "PE = ½ C (ΔV)²", "PE = ½ Q²/C", "All of the above options are correct."]'::jsonb,3,'Ministerial-style bank',132),
('physics',1,'Capacitors','Electric energy & variable conditions','en','The graphical representation of charge Q versus potential difference ΔV for a capacitor yields a straight line. The area under this curve represents:','["Resistance", "Electric potential energy (PE_elec)", "Electric field strength (E)", "Dielectric constant (k)"]'::jsonb,1,'Ministerial-style bank',133),
('physics',1,'Capacitors','Electric energy & variable conditions','en','How much energy is stored in a 2 μF capacitor charged to a potential difference of 100 V?','["0.01 J", "0.02 J", "100 J", "200 J"]'::jsonb,0,'Ministerial-style bank',134),
('physics',1,'Capacitors','Electric energy & variable conditions','en','If the potential difference across a capacitor is doubled while its capacitance remains constant, its stored energy will:','["Double", "Quadruple", "Decrease by half", "Remain unchanged"]'::jsonb,1,'Ministerial-style bank',135),
('physics',1,'Capacitors','Electric energy & variable conditions','en','Electric power (P) discharged from a capacitor in time interval t is calculated by:','["P = PE · t", "P = PE / t", "P = t / PE", "P = (Q · t)/ΔV"]'::jsonb,1,'Ministerial-style bank',136),
('physics',1,'Capacitors','Electric energy & variable conditions','en','A parallel-plate capacitor is charged and then disconnected from the battery. If the distance d between its plates is doubled, what happens to the electric field E between the plates?','["It doubles.", "It is halved.", "It remains unchanged.", "It quadruples."]'::jsonb,2,'Ministerial-style bank',137),
('physics',1,'Capacitors','Electric energy & variable conditions','en','A charged capacitor remains connected to a battery. If the distance d between its plates is halved, the stored charge Q will:','["Double", "Be halved", "Quadruple", "Remain constant"]'::jsonb,0,'Ministerial-style bank',138),
('physics',1,'Capacitors','Electric energy & variable conditions','en','A charged, disconnected capacitor has potential difference ΔV = 60 V. When a dielectric slab is inserted, the potential difference drops to 20 V. The dielectric constant k is:','["2", "3", "4", "0.33"]'::jsonb,1,'Ministerial-style bank',139),
('physics',1,'المتسعات','الموصلات المعزولة','ar','نادراً ما يُستعمل موصل كروي معزول مشحون لخزن كميات كبيرة من الشحنة الكهربائية لأن:','["مساحة سطحه صغيرة جداً لحمل الشحنة.", "زيادة شحنته ترفع جهده بشكل كبير مما يسبب تفريغاً كهربائياً في الهواء المحيط.", "يمكنه خزن الشحنات السالبة فقط.", "لا يمتلك مقاومة كهربائية."]'::jsonb,1,'Ministerial-style bank',100),
('physics',1,'المتسعات','الموصلات المعزولة','ar','يُحسب الجهد الكهربائي V على بعد r من مركز موصل كروي صلد معزول يحمل شحنة Q في الهواء بالعلاقة:','["V = k r / Q", "V = k Q / r", "V = k Q / r²", "V = Q / (ε₀ r)"]'::jsonb,1,'Ministerial-style bank',101),
('physics',1,'المتسعات','الموصلات المعزولة','ar','ماذا يحدث للهواء حول موصل كروي معزول عندما يتجاوز مجاله الكهربائي حوالي 3 × 10⁶ V/m؟','["يتحول الهواء إلى عازل مثالي.", "يحدث انهيار كهربائي فتتسرب الشحنة إلى الهواء.", "يفقد الموصل جهده مع احتفاظه بشحنته.", "يتجمد الهواء المحيط."]'::jsonb,1,'Ministerial-style bank',102),
('physics',1,'المتسعات','الموصلات المعزولة','ar','منظومة تتألف من موصلين يفصل بينهما عازل وتُستعمل لخزن الشحنة والطاقة الكهربائية تسمى:','["مقاومة", "محث", "متسعة", "كلفانوميتر"]'::jsonb,2,'Ministerial-style bank',103),
('physics',1,'المتسعات','الموصلات المعزولة','ar','في المتسعة ذات اللوحين المتوازيين يُعد المجال الكهربائي E بين اللوحين (بعيداً عن الحافات) منتظماً لأن:','["المسافة بين اللوحين أصغر بكثير من الأبعاد الخطية للوحين.", "اللوحان مصنوعان من مادة غير موصلة.", "فرق الجهد يساوي صفراً دائماً.", "اللوحان مربوطان بمصدر تيار متناوب."]'::jsonb,0,'Ministerial-style bank',104),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','تُعرَّف السعة (C) رياضياً بأنها النسبة بين:','["المجال الكهربائي والمسافة بين اللوحين (E / d)", "الشحنة المخزونة على أحد اللوحين وفرق الجهد بينهما (Q / ΔV)", "فرق الجهد والشحنة المخزونة (ΔV / Q)", "طاقة الوضع المخزونة والمقاومة (PE / R)"]'::jsonb,1,'Ministerial-style bank',105),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','وحدة السعة في النظام الدولي هي الفاراد (F)، والفاراد الواحد يكافئ:','["1 فولت / كولوم", "1 كولوم × فولت", "1 كولوم / فولت", "1 جول / كولوم"]'::jsonb,2,'Ministerial-style bank',106),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','أي التحويلات الآتية صحيح؟','["1 μF = 10⁻³ F", "1 nF = 10⁻⁶ F", "1 pF = 10⁻¹² F", "1 mF = 10⁻¹² F"]'::jsonb,2,'Ministerial-style bank',107),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','المجال الكهربائي E بين لوحين متوازيين مشحونين تفصلهما مسافة d عند فرق جهد ΔV يُعطى بالعلاقة:','["E = ΔV · d", "E = ΔV / d", "E = d / ΔV", "E = Q / (ΔV · d)"]'::jsonb,1,'Ministerial-style bank',108),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','كيف تتغير سعة متسعة ذات لوحين متوازيين إذا تضاعفت مساحة التداخل A للوحين مع ثبوت بقية العوامل؟','["تقل إلى النصف.", "تتضاعف.", "تصبح أربعة أمثال.", "لا تتغير."]'::jsonb,1,'Ministerial-style bank',109),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','كيف تتغير السعة إذا قُلِّلت المسافة d بين اللوحين إلى ثلث قيمتها الأصلية؟','["تقل إلى 1/3 من قيمتها الأصلية.", "لا تتغير.", "تزداد إلى 3 أمثال قيمتها الأصلية.", "تزداد إلى 9 أمثال قيمتها الأصلية."]'::jsonb,2,'Ministerial-style bank',110),
('physics',1,'المتسعات','السعة ومعاملات اللوحين المتوازيين','ar','الصيغة الرياضية لسعة متسعة ذات لوحين متوازيين والوسط بينهما هواء هي:','["C = ε₀ d / A", "C = ε₀ A / d", "C = ε₀ A d", "C = A / (ε₀ d)"]'::jsonb,1,'Ministerial-style bank',111),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','تختلف العوازل القطبية (مثل الماء النقي) عن العوازل غير القطبية لأن العوازل القطبية:','["تمتلك عزوماً ثنائية القطب كهربائية دائمية.", "تكتسب عزوماً ثنائية القطب مؤقتة فقط عند تعرضها لمجال كهربائي.", "توصل الكهرباء بسهولة.", "لا تتأثر بالمجالات الكهربائية الخارجية."]'::jsonb,0,'Ministerial-style bank',112),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','عند وضع مادة عازلة غير قطبية (كالزجاج أو البارافين) في مجال كهربائي فإن جزيئاتها:','["تصطف بشكل دائمي دون اكتساب شحنة.", "تستقطب مؤقتاً نتيجة إزاحة مركزي الشحنة الموجبة والسالبة.", "تكتسب إلكترونات حرة وتتحول إلى موصل فلزي.", "تفقد كل سلوك ثنائي القطب."]'::jsonb,1,'Ministerial-style bank',113),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','المجال الكهربائي المستحث E_d المتولد داخل العازل المُدخل بين لوحي متسعة مشحونة يكون اتجاهه:','["موازياً وبنفس اتجاه المجال الخارجي E.", "معاكساً لاتجاه المجال الكهربائي الخارجي E.", "عمودياً على المجال الخارجي E.", "دائرياً حول حافات اللوحين."]'::jsonb,1,'Ministerial-style bank',114),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','المجال الكهربائي المحصل E_k داخل مادة عازلة موضوعة في مجال خارجي E يُعطى بـ:','["E_k = E + E_d", "E_k = E − E_d", "E_k = E · E_d", "E_k = E_d / E"]'::jsonb,1,'Ministerial-style bank',115),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','ثابت العزل k لمادة ما هو نسبة عديمة الوحدات تُعرَّف بأنها:','["k = C / C_k", "k = C_k / C", "k = ΔV_k / ΔV", "k = C_k − C"]'::jsonb,1,'Ministerial-style bank',116),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','في تجربة فاراداي باستعمال كشاف كهربائي مرتبط بمتسعة مشحونة مفصولة عن المصدر، فإن إدخال شريحة عازلة يجعل انفراج ورقتي الكشاف:','["يزداد، دلالة على زيادة فرق الجهد.", "يقل، دلالة على نقصان فرق الجهد.", "ينعدم فوراً.", "يبقى دون تغيير."]'::jsonb,1,'Ministerial-style bank',117),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','ماذا يحدث لفرق الجهد بين لوحي متسعة مفصولة عن المصدر عند إدخال عازل ثابت عزله k = 4؟','["يزداد 4 مرات.", "يقل إلى 1/4 من قيمته الأصلية.", "يبقى ثابتاً.", "يتضاعف."]'::jsonb,1,'Ministerial-style bank',118),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','تُعرَّف متانة العزل بأنها أكبر مجال كهربائي تتحمله المادة قبل حدوث الانهيار، ووحدتها في النظام الدولي هي:','["فولت · متر", "فولت / متر", "فاراد / متر", "كولوم / فولت"]'::jsonb,1,'Ministerial-style bank',119),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','إذا أُدخلت مادة عازلة ثابت عزلها k = 3 في متسعة تبقى مرتبطة ببطارية مستمرة، فإن فرق الجهد بين اللوحين:','["يصبح ثلاثة أمثاله.", "يقل إلى الثلث.", "يبقى مساوياً لجهد البطارية.", "يصبح صفراً."]'::jsonb,2,'Ministerial-style bank',120),
('physics',1,'المتسعات','العوازل والأنشطة العملية','ar','إذا أُدخل عازل ثابت عزله k = 5 في متسعة مرتبطة ببطارية 12 V، فإن شحنة المتسعة:','["تقل بمقدار 5 مرات.", "تزداد 5 مرات.", "تبقى ثابتة.", "تصبح صفراً."]'::jsonb,1,'Ministerial-style bank',121),
('physics',1,'المتسعات','ربط المتسعات','ar','عند ربط المتسعات على التوازي مع مصدر جهد مستمر، أي كمية تبقى متساوية لجميع المتسعات؟','["الشحنة الكهربائية (Q)", "فرق الجهد (ΔV)", "الطاقة المخزونة (PE)", "السعة (C)"]'::jsonb,1,'Ministerial-style bank',122),
('physics',1,'المتسعات','ربط المتسعات','ar','السبب العملي الأساس لربط المتسعات على التوازي هو:','["زيادة السعة المكافئة وخزن كمية أكبر من الشحنة عند فرق جهد معين.", "تمكين المنظومة من تحمل فرق جهد أعلى دون انهيار.", "تقليل الطاقة الكلية المخزونة.", "تحويل التيار المستمر إلى متناوب."]'::jsonb,0,'Ministerial-style bank',123),
('physics',1,'المتسعات','ربط المتسعات','ar','السعة المكافئة C_eq لثلاث متسعات (C₁, C₂, C₃) مربوطة على التوازي تُحسب بـ:','["C_eq = 1/C₁ + 1/C₂ + 1/C₃", "C_eq = C₁ + C₂ + C₃", "1/C_eq = 1/C₁ + 1/C₂ + 1/C₃", "C_eq = (C₁·C₂·C₃)/(C₁ + C₂ + C₃)"]'::jsonb,1,'Ministerial-style bank',124),
('physics',1,'المتسعات','ربط المتسعات','ar','في الربط على التوالي للمتسعات، فإن الشحنة الكلية Q_T المجهزة من المصدر تساوي:','["Q₁ + Q₂ + Q₃", "Q₁ = Q₂ = Q₃", "(Q₁ + Q₂)/Q₃", "صفر"]'::jsonb,1,'Ministerial-style bank',125),
('physics',1,'المتسعات','ربط المتسعات','ar','ما الغرض الأساس من ربط المتسعات على التوالي؟','["زيادة خزن الشحنة الكلية إلى أقصى حد.", "تسليط فرق جهد عالٍ على المجموعة لا تستطيع متسعة منفردة تحمله.", "زيادة مساحة سطح اللوحين لكل متسعة.", "زيادة السعة المكافئة الكلية."]'::jsonb,1,'Ministerial-style bank',126),
('physics',1,'المتسعات','ربط المتسعات','ar','السعة المكافئة C_eq للربط على التوالي تكون دائماً:','["أكبر من أكبر سعة منفردة في المجموعة.", "مساوية لمعدل السعات جميعها.", "أصغر من أصغر سعة منفردة في المجموعة.", "ضعف قيمة أكبر سعة."]'::jsonb,2,'Ministerial-style bank',127),
('physics',1,'المتسعات','ربط المتسعات','ar','رُبطت متسعتان C₁ = 6 μF و C₂ = 12 μF على التوالي، فما سعتهما المكافئة C_eq؟','["18 μF", "4 μF", "0.25 μF", "72 μF"]'::jsonb,1,'Ministerial-style bank',128),
('physics',1,'المتسعات','ربط المتسعات','ar','رُبطت متسعتان (C₁ = 3 μF و C₂ = 6 μF) على التوازي مع بطارية 12 V، فما مقدار الشحنة الكلية المخزونة Q_T؟','["36 μC", "72 μC", "108 μC", "144 μC"]'::jsonb,2,'Ministerial-style bank',129),
('physics',1,'المتسعات','ربط المتسعات','ar','في ربط متسعتين غير متساويتين على التوالي (C₁ < C₂)، أي متسعة يتسلط عليها فرق الجهد الأكبر؟','["C₁ (المتسعة الأصغر)", "C₂ (المتسعة الأكبر)", "كلتاهما بفرق الجهد نفسه تماماً.", "لا يتسلط فرق جهد على أي منهما."]'::jsonb,0,'Ministerial-style bank',130),
('physics',1,'المتسعات','ربط المتسعات','ar','إذا رُبطت ثلاث متسعات متماثلة سعة كل منها C على التوازي، فإن السعة المكافئة هي:','["C/3", "C", "3C", "9C"]'::jsonb,2,'Ministerial-style bank',131),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','أي المعادلات الآتية يمثل بشكل صحيح طاقة الوضع الكهربائية (PE_elec) المخزونة في متسعة مشحونة؟','["PE = ½ Q ΔV", "PE = ½ C (ΔV)²", "PE = ½ Q²/C", "جميع ما ذُكر صحيح."]'::jsonb,3,'Ministerial-style bank',132),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','التمثيل البياني للشحنة Q مقابل فرق الجهد ΔV لمتسعة يعطي خطاً مستقيماً، والمساحة تحت هذا الخط تمثل:','["المقاومة", "طاقة الوضع الكهربائية (PE_elec)", "شدة المجال الكهربائي (E)", "ثابت العزل (k)"]'::jsonb,1,'Ministerial-style bank',133),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','ما مقدار الطاقة المخزونة في متسعة سعتها 2 μF شُحنت إلى فرق جهد 100 V؟','["0.01 J", "0.02 J", "100 J", "200 J"]'::jsonb,0,'Ministerial-style bank',134),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','إذا تضاعف فرق الجهد بين لوحي متسعة مع بقاء سعتها ثابتة، فإن الطاقة المخزونة:','["تتضاعف", "تصبح أربعة أمثال", "تقل إلى النصف", "لا تتغير"]'::jsonb,1,'Ministerial-style bank',135),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','القدرة الكهربائية P المتحررة من متسعة خلال فترة زمنية t تُحسب بـ:','["P = PE · t", "P = PE / t", "P = t / PE", "P = (Q · t)/ΔV"]'::jsonb,1,'Ministerial-style bank',136),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','شُحنت متسعة ذات لوحين متوازيين ثم فُصلت عن البطارية. إذا تضاعفت المسافة d بين اللوحين فماذا يحدث للمجال الكهربائي E بينهما؟','["يتضاعف.", "يقل إلى النصف.", "يبقى دون تغيير.", "يصبح أربعة أمثاله."]'::jsonb,2,'Ministerial-style bank',137),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','متسعة مشحونة تبقى مرتبطة بالبطارية، إذا قُلِّلت المسافة d بين لوحيها إلى النصف فإن الشحنة المخزونة Q:','["تتضاعف", "تقل إلى النصف", "تصبح أربعة أمثال", "تبقى ثابتة"]'::jsonb,0,'Ministerial-style bank',138),
('physics',1,'المتسعات','الطاقة الكهربائية والحالات المتغيرة','ar','متسعة مشحونة مفصولة عن المصدر فرق الجهد بين لوحيها ΔV = 60 V، وعند إدخال شريحة عازلة انخفض فرق الجهد إلى 20 V، فما ثابت العزل k؟','["2", "3", "4", "0.33"]'::jsonb,1,'Ministerial-style bank',139);
